import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md","lastUpdated":1792570296000}'),i={name:"reference/troubleshooting.md"};function n(s,e,d,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Find your symptom in the index, check the likely cause, then follow the link to the fix. Start with the visible task state and error message: a slow upstream service, a queued task, and a disconnected browser need different responses.</p><h2 id="symptom-index" tabindex="-1">Symptom index <a class="header-anchor" href="#symptom-index" aria-label="Permalink to &quot;Symptom index&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Go to</th></tr></thead><tbody><tr><td>A search takes a long time</td><td>Queued task, large budget, or a slow upstream stage</td><td><a href="#a-search-is-taking-a-long-time">Search problems</a></td></tr><tr><td>HTTP 401 / 403</td><td>Wrong key or missing provider permission</td><td><a href="#http-401-403-404-or-429">HTTP errors</a></td></tr><tr><td>HTTP 404</td><td>Wrong base URL, protocol, route, or model</td><td><a href="#http-401-403-404-or-429">HTTP errors</a></td></tr><tr><td>HTTP 429</td><td>Provider rate limit or insufficient credit</td><td><a href="#http-401-403-404-or-429">HTTP errors</a></td></tr><tr><td>Connection error / timeout</td><td>Network reachability or provider availability</td><td><a href="#http-401-403-404-or-429">HTTP errors</a></td></tr><tr><td>Your endpoint is rejected online</td><td>Non-public address (localhost, private network)</td><td><a href="#my-endpoint-is-rejected-online">My endpoint is rejected online</a></td></tr><tr><td>No results, missing abstracts, or counts differ</td><td>Over-restrictive query or gaps in the source record</td><td><a href="#no-results-missing-abstracts-or-different-counts">No results</a></td></tr><tr><td>The citation map is empty</td><td>Source without expansion, or no links within budget</td><td><a href="#the-citation-map-is-empty">The citation map is empty</a></td></tr><tr><td>A review outline or section fails</td><td>Model availability or a provider error</td><td><a href="#a-review-outline-or-section-fails">A review outline or section fails</a></td></tr><tr><td>Auto-select by topic returns nothing usable</td><td>The writing model returned an invalid list or could not be reached</td><td><a href="#auto-select-by-topic-returns-nothing-usable">Auto-select by topic returns nothing usable</a></td></tr><tr><td>The local service cannot start</td><td>Python version, database path, or port conflict</td><td><a href="#local-service-cannot-start">Local service cannot start</a></td></tr><tr><td>Sign-in or email-code problems</td><td>Spam folder, expired or replaced code</td><td><a href="./../online/account#email-or-password-problems">Your account</a></td></tr></tbody></table><h2 id="search-problems" tabindex="-1">Search problems <a class="header-anchor" href="#search-problems" aria-label="Permalink to &quot;Search problems&quot;">​</a></h2><h3 id="a-search-is-taking-a-long-time" tabindex="-1">A search is taking a long time <a class="header-anchor" href="#a-search-is-taking-a-long-time" aria-label="Permalink to &quot;A search is taking a long time&quot;">​</a></h3><p>Check whether the task is <strong>queued</strong> or <strong>running</strong>. Up to four tasks run at once by default; the rest wait in the queue (see <a href="./configuration#concurrent-tasks">concurrent tasks</a>). During execution, query refinement, source requests, citation expansion, and model scoring can each take time. Larger budgets make more work possible but do not guarantee more useful results.</p><p>If the page loses its connection, reopen the saved run and inspect its status before submitting again. Anonymous online results are temporary; see <a href="./../online/privacy#search-without-signing-in">Data &amp; privacy</a>.</p><h3 id="no-results-missing-abstracts-or-different-counts" tabindex="-1">No results, missing abstracts, or different counts <a class="header-anchor" href="#no-results-missing-abstracts-or-different-counts" aria-label="Permalink to &quot;No results, missing abstracts, or different counts&quot;">​</a></h3><p>Broaden the question, remove overly restrictive fields, or try a more suitable source. Source hits are not the number downloaded, and downloaded candidates are not the final ranked set.</p><p>Missing abstracts, citation counts, or PDFs can be a property of the source record. PaperSeek does not independently fill missing abstracts from another source.</p><h3 id="the-citation-map-is-empty" tabindex="-1">The citation map is empty <a class="header-anchor" href="#the-citation-map-is-empty" aria-label="Permalink to &quot;The citation map is empty&quot;">​</a></h3><p>Check that the run used a supported citation-expansion source and that expansion was enabled. Even then, the source may provide no usable links within the available budget.</p><h2 id="http-and-provider-errors" tabindex="-1">HTTP and provider errors <a class="header-anchor" href="#http-and-provider-errors" aria-label="Permalink to &quot;HTTP and provider errors&quot;">​</a></h2><h3 id="http-401-403-404-or-429" tabindex="-1">HTTP 401, 403, 404, or 429 <a class="header-anchor" href="#http-401-403-404-or-429" aria-label="Permalink to &quot;HTTP 401, 403, 404, or 429&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Error</th><th>Check</th></tr></thead><tbody><tr><td>401 / 403</td><td>Correct key, provider account permissions, and selected model</td></tr><tr><td>404</td><td>API base URL, protocol, route, model availability, or a missing task/resource</td></tr><tr><td>429</td><td>Provider rate limit or structured insufficient-credit error</td></tr><tr><td>Connection / timeout</td><td>Network reachability and provider availability; if the service is blocked on your network, set up a <a href="./configuration#network-proxy">network proxy</a></td></tr></tbody></table><p>A 404 displayed during an OpenAlex run does not by itself prove that OpenAlex returned it: model requests and application routes also occur during the task. Record the stage, safe error code, task ID, and time.</p><p>PaperSeek Service credits and an upstream provider&#39;s balance are different. Increasing one does not change the other.</p><h3 id="my-endpoint-is-rejected-online" tabindex="-1">My endpoint is rejected online <a class="header-anchor" href="#my-endpoint-is-rejected-online" aria-label="Permalink to &quot;My endpoint is rejected online&quot;">​</a></h3><p>Online, your own key cannot point to localhost, private networks, and other non-public destinations. Use a public provider URL, or use Community for a model running on your own machine. A valid URL must also implement the chosen API protocol.</p><h2 id="review-problems" tabindex="-1">Review problems <a class="header-anchor" href="#review-problems" aria-label="Permalink to &quot;Review problems&quot;">​</a></h2><h3 id="a-review-outline-or-section-fails" tabindex="-1">A review outline or section fails <a class="header-anchor" href="#a-review-outline-or-section-fails" aria-label="Permalink to &quot;A review outline or section fails&quot;">​</a></h3><p>Review writing is experimental and depends on selected evidence and model availability. Select papers with useful abstracts, inspect the current project/job state, and retry the failed work after resolving the reported provider issue. Avoid repeatedly creating duplicate projects.</p><p>Longer drafts need more output from the model. A completed outline does not guarantee that the next writing request will succeed. Keep manual edits and inspect versions before regenerating.</p><p>When one section fails, the other sections are still written and saved. Retrying writes only the sections that are missing or need revision.</p><h3 id="auto-select-by-topic-returns-nothing-usable" tabindex="-1">Auto-select by topic returns nothing usable <a class="header-anchor" href="#auto-select-by-topic-returns-nothing-usable" aria-label="Permalink to &quot;Auto-select by topic returns nothing usable&quot;">​</a></h3><p>The writing model did not return a valid list, or could not be reached. Check the writing model in the setup step, try again, or tick papers yourself. Auto-select only proposes papers; nothing is created until you generate the outline.</p><h2 id="local-service" tabindex="-1">Local service <a class="header-anchor" href="#local-service" aria-label="Permalink to &quot;Local service&quot;">​</a></h2><h3 id="local-service-cannot-start" tabindex="-1">Local service cannot start <a class="header-anchor" href="#local-service-cannot-start" aria-label="Permalink to &quot;Local service cannot start&quot;">​</a></h3><p>Run <code>paperseek doctor --json</code>. Check Python 3.12+, the selected database path, write permissions, port conflicts, and model settings. Read the launching terminal or service manager&#39;s logs; the Web UI intentionally focuses on status rather than raw execution logs.</p><p>For separate processes, confirm both API and worker use the same database.</p><h2 id="report-a-reproducible-issue" tabindex="-1">Report a reproducible issue <a class="header-anchor" href="#report-a-reproducible-issue" aria-label="Permalink to &quot;Report a reproducible issue&quot;">​</a></h2><p>Open a <a href="https://github.com/paperseek/paperseek/issues" target="_blank" rel="noreferrer">GitHub issue</a> with:</p><ul><li>Installed version or online mode, browser/OS, and steps to reproduce.</li><li>Source, protocol, ranking method, and budget.</li><li>Expected behavior, observed error, task ID if appropriate, and approximate time.</li><li>A minimal non-sensitive example and a cropped screenshot if helpful.</li></ul><p>Remove API keys, passwords, verification codes, cookies, private queries, and identifying data. Security reports belong in the repository&#39;s <a href="https://github.com/paperseek/paperseek/blob/main/SECURITY.md" target="_blank" rel="noreferrer">security process</a>.</p>',35)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
